begin;
delete from public.immunizations where child_id in (select c.id from public.children c left join public.posyandu p on c.posyandu_id = p.id where c.is_demo and (p.puskesmas_id = '5f04d88d-2a0c-4b9a-987b-1638a5cf3492' or c.name like 'Anak Uji %'));
delete from public.measurements where child_id in (select c.id from public.children c left join public.posyandu p on c.posyandu_id = p.id where c.is_demo and (p.puskesmas_id = '5f04d88d-2a0c-4b9a-987b-1638a5cf3492' or c.name like 'Anak Uji %'));
delete from public.children where id in (select c.id from public.children c left join public.posyandu p on c.posyandu_id = p.id where c.is_demo and (p.puskesmas_id = '5f04d88d-2a0c-4b9a-987b-1638a5cf3492' or c.name like 'Anak Uji %'));
delete from public.posyandu where is_demo and puskesmas_id = '5f04d88d-2a0c-4b9a-987b-1638a5cf3492' and name like 'Candrarini %';
commit;
